function finishDrag(){if(pendingSketch){if(pendingSketch.line.points.length>1){undo.push(pendingSketch.before);if(undo.length>60)undo.shift();redo=[];status('Sketch added — unsaved changes');scheduleDraftSave()}else look=pendingSketch.before;pendingSketch=null;render();return}if(!drag)return;if(JSON.stringify(drag.before)!==JSON.stringify(look)){undo.push(drag.before);if(undo.length>60)undo.shift();redo=[];status('Unsaved changes');scheduleDraftSave()}drag=null;render()}
