canvas.onkeydown=event=>{const line=(event.target as Element).closest<SVGElement>('[data-line]');if(line&&(event.key==='Delete'||event.key==='Backspace')){event.preventDefault();const index=Number(line.dataset.line);commit(state=>state.sketch.splice(index,1));return}const target=(event.target as Element).closest<SVGGElement>('[data-id]');if(!target)return;selected=target.dataset.id!;if(event.key==='Delete'||event.key==='Backspace'){event.preventDefault();removeDetail();return}const deltas:Record<string,[number,number]>={ArrowUp:[0,-3],ArrowDown:[0,3],ArrowLeft:[-3,0],ArrowRight:[3,0]};const delta=deltas[event.key];if(!delta)return;event.preventDefault();commit(state=>{const d=state.details.find(v=>v.id===selected);if(d){d.x=Math.max(125,Math.min(375,d.x+delta[0]));d.y=Math.max(175,Math.min(610,d.y+delta[1]))}});canvas.querySelector<SVGGElement>(`[data-id="${selected}"]`)?.focus()}
canvas.addEventListener('focusin',event=>{const id=(event.target as Element).closest<SVGGElement>('[data-id]')?.dataset.id;if(id&&id!==selected){selected=id;get<HTMLInputElement>('detailSize').disabled=false;get<HTMLInputElement>('detailSize').value=String(look.details.find(d=>d.id===id)?.size??18);get<HTMLButtonElement>('removeDetail').disabled=false}})
get('undo').onclick=()=>{const previous=undo.pop();if(previous){redo.push(snapshot(look));look=previous;selected='';render();status('Undone — unsaved changes');scheduleDraftSave()}}
get('redo').onclick=()=>{const next=redo.pop();if(next){undo.push(snapshot(look));look=next;selected='';render();status('Redone — unsaved changes');scheduleDraftSave()}}
