get('save').onclick=async()=>{syncTextFields();try{const next=[snapshot(look),...saved.filter(d=>d.name!==look.name)].slice(0,12);const warning=await saveLooks(next);saved=next;savedButtons();status(warning||`Saved ${look.name} to your account and this device`)}catch{status('Device storage is unavailable. Download the design file to keep your look.')}}
