get<HTMLDialogElement>('reviewDialog').addEventListener('close',syncReview);
function review(){syncTextFields();const host=get('reviewBody');const src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 760">${illustration()}</svg>`);host.innerHTML=`<div class="review-grid"><section><h3>Your requested design</h3><div class="review-image"><img alt="Requested outfit illustration" src="${src}"></div><div class="review-colours">${colourRows(look).map(r=>`<span><b>${escapeHTML(r.label)}</b><br>${escapeHTML(r.name)}<br>${escapeHTML(r.hex.toUpperCase())}</span>`).join('')}</div><p class="fine">Approximate screen colours. Fabric swatch approval is needed before cutting.</p></section><section><h3>The details that matter</h3><details><summary>Garment and accessory specification</summary><ul>${designLines(look).map(line=>`<li>${escapeHTML(line)}</li>`).join('')}<li>${escapeHTML(accessoryDescriptions(look).join(', ')||'No accessories')}</li></ul></details>${look.reference?`<img class="review-reference" alt="Original inspiration reference" src="${look.reference.image}"><p class="fine">Original inspiration — describe what carries over.</p>`:'<p class="fine">No source photo. Describe the intention behind your original idea.</p>'}${(['keep','change','remove','confirm'] as const).map((key,i)=>`<label for="direction-${key}">${i+1}. ${({keep:'Keep',change:'Change',remove:'Remove',confirm:'Ask the tailor to confirm'})[key]}</label><textarea id="direction-${key}" maxlength="300" rows="2" placeholder="${({keep:'e.g. silhouette, neckline, fabric feel',change:'e.g. length, fit, fabric or sleeve detail',remove:'e.g. remove the belt',confirm:'e.g. construction, lining, fabric and movement'})[key]}">${escapeHTML(look.directions[key]||(key==='keep'?look.reference?.keep:key==='change'?look.reference?.change:'')||'')}</textarea>`).join('')}</section></div>`;
 for(const k of ['keep','change','remove','confirm'] as const)get<HTMLTextAreaElement>(`direction-${k}`).oninput=()=>{const value=get<HTMLTextAreaElement>(`direction-${k}`).value;commit(s=>{s.directions[k]=value;if(s.reference&&k==='keep')s.reference.keep=value;if(s.reference&&k==='change')s.reference.change=value})};get<HTMLDialogElement>('reviewDialog').showModal();}
function usedColours():(typeof colourPart)[]{return [...(look.outfit==='blank'?[]:['colour']),...(look.outfit==='dress'||look.outfit==='jumpsuit'||look.outfit==='blank'?[]:['lowerColour']),...(look.outer==='none'?[]:['outerColour']),...(look.headwear?['headColour']:[]),'shoeColour','accentColour'] as (typeof colourPart)[]}
function syncReview(){for(const k of ['keep','change','remove','confirm'] as const){const el=document.getElementById(`direction-${k}`) as HTMLTextAreaElement|null;if(el){look.directions[k]=el.value.slice(0,300);if(look.reference&&(k==='keep'||k==='change'))look.reference[k]=look.directions[k];let printable=el.nextElementSibling as HTMLElement|null;if(!printable?.classList.contains('print-value')){printable=document.createElement('div');printable.className='print-value';el.after(printable)}printable.textContent=el.value||'Not specified'}}}
function notesText(){return renderTransferNotes(look)}
get('review').onclick=review;get('editReview').onclick=()=>{syncReview();get<HTMLDialogElement>('reviewDialog').close()};get('textReview').onclick=()=>{syncReview();download(notesText(),'text/plain','txt','drapeon-design-directions')};
get('pngReview').onclick=async()=>{syncReview();const button=get<HTMLButtonElement>('pngReview');button.disabled=true;button.textContent='Preparing image…';try{const svg=reviewSVG(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const img=new Image();await new Promise<void>((resolve,reject)=>{img.onload=()=>resolve();img.onerror=()=>reject(new Error('Image rendering failed'));img.src=url});const c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;const ctx=c.getContext('2d');if(!ctx)throw Error('Canvas unavailable');ctx.drawImage(img,0,0);const blob=await new Promise<Blob>((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error('PNG export unavailable')),'image/png'));const data=c.toDataURL('image/png');get<HTMLImageElement>('pngImage').src=data;get<HTMLAnchorElement>('pngSave').href=data;get<HTMLDialogElement>('pngPreview').showModal();button.textContent='View PNG sheet'}finally{URL.revokeObjectURL(url)}}catch{button.textContent='PNG unavailable — use SVG or Print'}finally{button.disabled=false}};
get('printReview').onclick=()=>{syncReview();window.print()};
get('downloadReview').onclick=()=>{syncReview();download(reviewSVG(),'image/svg+xml','svg','drapeon-design-sheet')};
function briefHandoffNotes(){return buildBriefHandoffNotes(look)}
get<HTMLButtonElement>('attachToBrief').hidden=!canAttachToBrief();
get<HTMLButtonElement>('reviseOrder').hidden=!revisingOrderVersion();
get<HTMLElement>('orderRevisionFields').hidden=!revisingOrderVersion();
get<HTMLElement>('tailorProposalFields').hidden=!sourceVersion;
get<HTMLButtonElement>('proposeStylePlan').hidden=!sourceVersion;
async function reviewPNG(){const url=URL.createObjectURL(new Blob([reviewSVG()],{type:'image/svg+xml'}));try{const image=new Image();await new Promise<void>((resolve,reject)=>{image.onload=()=>resolve();image.onerror=()=>reject(Error('The design sheet could not be rendered.'));image.src=url});const canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;const context=canvas.getContext('2d');if(!context)throw Error('Image export is unavailable.');context.drawImage(image,0,0);const data=canvas.toDataURL('image/png');if(data.length>9_000_000)throw Error('This sheet is too large to attach. Shorten the notes or remove the inspiration image, then try again.');return data}finally{URL.revokeObjectURL(url)}}
get('reviseOrder').onclick=async()=>{syncReview();const note=get<HTMLTextAreaElement>('orderRevisionNote').value.trim();if(note.length<5){status('Describe what changed in at least five characters.');get<HTMLTextAreaElement>('orderRevisionNote').focus();return}const button=get<HTMLButtonElement>('reviseOrder');button.disabled=true;button.textContent='Sending updated design…';try{await reviseOrder(await reviewPNG(),snapshot(look),note);button.textContent='Design sent to your order'}catch(error){button.disabled=false;button.textContent='Send updated design to order';status(error instanceof Error?error.message:'The design could not be sent.')}};
get('proposeStylePlan').onclick=async()=>{syncReview();const note=get<HTMLTextAreaElement>('tailorProposalNote').value.trim();if(note.length<10){status('Explain your style plan in at least ten characters.');get<HTMLTextAreaElement>('tailorProposalNote').focus();return}const button=get<HTMLButtonElement>('proposeStylePlan');button.disabled=true;button.textContent='Sending style plan…';try{await proposeStylePlan(await reviewPNG(),note);button.textContent='Style plan sent for customer approval'}catch(error){button.disabled=false;button.textContent='Send style plan for approval';status(error instanceof Error?error.message:'The style plan could not be sent.')}};
get('attachToBrief').onclick=async()=>{syncReview();const button=get<HTMLButtonElement>('attachToBrief');button.disabled=true;button.textContent='Preparing brief reference…';try{const svg=reviewSVG(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const image=new Image();await new Promise<void>((resolve,reject)=>{image.onload=()=>resolve();image.onerror=()=>reject(Error('The design sheet could not be rendered.'));image.src=url});const canvas=document.createElement('canvas');canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;const context=canvas.getContext('2d');if(!context)throw Error('Image export is unavailable.');context.drawImage(image,0,0);const data=canvas.toDataURL('image/png');if(data.length>9_000_000)throw Error('This sheet is too large to attach. Shorten the notes or remove the inspiration image, then try again.');attachBrief(data,briefHandoffNotes(),`${look.name} — Sketch Room sheet`,snapshot(look));button.textContent='Returning to your brief…'}finally{URL.revokeObjectURL(url)}}catch(error){button.disabled=false;button.textContent='Attach design to brief';status(error instanceof Error?error.message:'The design could not be attached.')}};
function reviewSVG(){return renderLookSheet(look,illustration())}
get('panelColour').onchange=()=>commit(s=>s.panelColour=get<HTMLInputElement>('panelColour').value);
get('necklaceLayers').onchange=()=>commit(s=>{s.necklaceLayers=Number(get<HTMLSelectElement>('necklaceLayers').value);s.beads=true});
get('cane').onclick=()=>{commit(s=>{s.cane=!s.cane;if(s.cane){s.pose='resting';s.fan=false;if(s.bag==='clutch')s.bag='none'}});status('Cane grip uses relaxed arms. Undo restores your previous pose.')};
for(const id of ['earringStyle','beadFinish','caneStyle'] as const)get(id).onchange=()=>commit(s=>{(s as any)[id]=get<HTMLSelectElement>(id).value;if(id==='earringStyle')s.earrings=true;if(id==='beadFinish')s.beads=true;if(id==='caneStyle'){s.cane=true;s.fan=false;if(s.bag==='clutch')s.bag='none';s.pose='resting'}});
const accessoryIcons:Record<string,string>={earrings:'<circle cx="12" cy="6" r="2"/><path d="M12 9Q4 15 12 22Q20 15 12 9Z"/>',beads:'<path d="M3 5Q3 26 12 25Q21 26 21 5" stroke-dasharray="2 3"/>',bracelet:'<ellipse cx="12" cy="15" rx="8" ry="5"/>',belt:'<path d="M2 12H22V18H2Z"/><rect x="9" y="11" width="6" height="8"/>',sunglasses:'<rect x="1" y="10" width="9" height="7" rx="2"/><rect x="14" y="10" width="9" height="7" rx="2"/><path d="M10 12H14"/>',watch:'<path d="M9 2H15V9H9ZM9 19H15V26H9Z"/><circle cx="12" cy="14" r="6"/>',cane:'<path d="M7 7Q7 1 13 3Q17 5 14 9L14 27"/>'};
for(const [id,icon]of Object.entries(accessoryIcons)){const b=get(id);const label=b.textContent;b.innerHTML=`<svg viewBox="0 0 24 30" width="25" height="32" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5">${icon}</svg><span>${label}</span>`;b.classList.add('accessory-tile')}
get('fan').onclick=()=>{commit(s=>{s.fan=!s.fan;if(s.fan){s.cane=false;s.pose='resting';if(s.bag==='clutch')s.bag='none'}});status('Fan uses a relaxed right-hand grip. Undo restores the previous look.')};
get('wrap').onchange=()=>commit(s=>s.wrap=get<HTMLSelectElement>('wrap').value as Look['wrap']);
get('wrapColour').onchange=()=>commit(s=>s.wrapColour=get<HTMLInputElement>('wrapColour').value);
get('bag').onchange=()=>commit(s=>{s.bag=get<HTMLSelectElement>('bag').value as Look['bag'];if(s.bag==='clutch'){s.cane=false;s.fan=false}});
get('colourTarget').onchange=()=>{colourTarget=get<HTMLSelectElement>('colourTarget').value;render()};
get('finish').onchange=()=>commit(s=>s.surfaces[surfaceKey(colourPart)].finish=get<HTMLSelectElement>('finish').value as 'matte'|'satin');
get('patternRotation').onchange=()=>commit(s=>s.surfaces[surfaceKey(colourPart)].rotation=Number(get<HTMLInputElement>('patternRotation').value));
get('hexColour').oninput=()=>{const v=get<HTMLInputElement>('hexColour').value.trim();if(/^#[0-9a-f]{6}$/i.test(v)){get('hexError').textContent='';writeColour(v.toLowerCase())}};
get('jumpsuitLeg').onchange=()=>commit(s=>s.bottom=get<HTMLSelectElement>('jumpsuitLeg').value as Look['bottom']);
get('hexColour').onchange=()=>{const v=get<HTMLInputElement>('hexColour').value.trim();if(!/^#[0-9a-f]{6}$/i.test(v)){get('hexError').textContent='Use # followed by six colour digits.';return}get('hexError').textContent='';writeColour(v.toLowerCase())};
syncColour=mountColour(readColour,writeColour);
const families:{label:string;values:Partial<Look>}[]=[
 {label:'Dress',values:{outfit:'dress',outer:'none',cut:'aline',length:'midi'}},
 {label:'Top & trousers',values:{outfit:'separates',top:'tee',bottom:'wide',outer:'none',length:'long'}},
 {label:'Blouse & skirt',values:{outfit:'separates',top:'blouse',bottom:'skirt',outer:'none',skirtShape:'aline',length:'midi'}},
 {label:'Jumpsuit',values:{outfit:'jumpsuit',bottom:'wide',outer:'none',length:'long'}},
 {label:'Coat & layers',values:{outfit:'separates',top:'shirt',bottom:'trousers',outer:'coat',length:'long'}},
 {label:'Tunic',values:{outfit:'tunic',outer:'none',length:'long'}},
 {label:'Agbada',values:{outfit:'agbada',outer:'agbada',length:'long'}}];
for(const f of families){const b=document.createElement('button');b.textContent=f.label;b.onclick=()=>{if(isEveryday(look))return;commit(s=>Object.assign(s,f.values,{canvasMode:'figure'}));selectPiece('colour');status(`${f.label} selected. Your colours and accessories are kept.`)};get('familyLaunch').append(b)}
for(const [id,mode]of [['editShape','shape'],['editColour','colour']] as const)get(id).onclick=()=>{document.querySelector<HTMLElement>('.inspector')!.dataset.mode=mode;get('editShape').setAttribute('aria-pressed',String(mode==='shape'));get('editColour').setAttribute('aria-pressed',String(mode==='colour'))};
placementUI=mountPlacement(canvas,{read:()=>look,commit,render,status,stopDrawing:()=>{drawMode=false;get('draw').setAttribute('aria-pressed','false')},select:id=>{colourPart=FIELDS[id] as typeof colourPart;colourTarget=id==='bag'?'bagColour':'piece';get<HTMLSelectElement>('colourTarget').value=colourTarget;get<HTMLSelectElement>('colourPart').value=colourPart;render()}});
everydayUI=mountEveryday({read:()=>look,commit,status,selected:()=>colourPart,select:field=>field==='accentColour'?selectBag():selectPiece(field)});
sketchImport=mountSketchImport({read:()=>look,commit,status});uxReady=true;fillCards();render();if(orderVersion){get('workspaceEyebrow').textContent=`REVISING ORDER DESIGN · VERSION ${orderVersion}`;get('reviewEyebrow').textContent=`ORDER DESIGN · VERSION ${orderVersion}`;get('reviewTitle').textContent='Review this update before sending.';status(`Working from order version ${orderVersion}. Changes stay on this device until you send them.`)}else if(sourceVersion){get('workspaceEyebrow').textContent=`TAILOR WORKING COPY · CUSTOMER VERSION ${sourceVersion}`;get('reviewEyebrow').textContent=`WORKING COPY · CUSTOMER VERSION ${sourceVersion}`;get('reviewTitle').textContent='Review your style plan before sharing.';status(`Customer design version ${sourceVersion} is open as your working copy. Review the sheet to send your style plan for approval.`)}else if(startMode()==='reference'){setRoom('reference');openMobileLibrary();status(recoveredDraft()?'Your latest draft is back. Add the photo or sketch you want to work from.':'Bring a look you already have, then describe what to keep and change.')}else if(startMode()==='saved'){get<HTMLDialogElement>('saveDialog').showModal();status('Choose a saved sketch to review for this brief.')}else if(recoveredDraft())status('Your latest draft is back.');else get<HTMLDialogElement>('welcome').showModal();if(storageNotice())status(storageNotice());

if(native){get('printReview').hidden=true;get<HTMLAnchorElement>('pngSave').onclick=event=>{event.preventDefault();const src=get<HTMLImageElement>('pngImage').src;void exportNative(src.split(',')[1]??'','image/png','png',true).then(()=>status('Image saved to your chosen folder.')).catch(error=>status(error.message))}}
